$('.youtube').each(
    function() {
        var $this = $(this), flashID = $this.attr('id'), uuid = $this
        .attr('class').replace(/youtube /, '');
        new YouTube(uuid, 300, 243, flashID);
    });
$('.youtube_big').each(
    function() {
        var $this = $(this), flashID = $this.attr('id'), uuid = $this
        .attr('class').replace(/youtube_big /, '');
        new YouTube(uuid, 960, 564, flashID);
    });


